## 2) 코드

### `ai-orchestrator.ts`

```ts
/* eslint-disable no-console */

export type AIMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type AIRequest = {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  metadata?: Record<string, unknown>;
};

export type AIResponse = {
  provider: string;
  model: string;
  text: string;
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    totalTokens?: number;
  };
  latencyMs: number;
  raw?: unknown;
};

export type ProviderCallContext = {
  signal?: AbortSignal;
  requestId?: string;
  logger?: Logger;
};

export interface Logger {
  info(message: string, meta?: Record<string, unknown>): void;
  warn(message: string, meta?: Record<string, unknown>): void;
  error(message: string, meta?: Record<string, unknown>): void;
  debug?(message: string, meta?: Record<string, unknown>): void;
}

export class ConsoleLogger implements Logger {
  info(message: string, meta?: Record<string, unknown>) {
    console.info(message, meta ?? {});
  }
  warn(message: string, meta?: Record<string, unknown>) {
    console.warn(message, meta ?? {});
  }
  error(message: string, meta?: Record<string, unknown>) {
    console.error(message, meta ?? {});
  }
  debug(message: string, meta?: Record<string, unknown>) {
    console.debug(message, meta ?? {});
  }
}

export type ProviderErrorCode =
  | "TIMEOUT"
  | "ABORTED"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "UPSTREAM"
  | "NETWORK"
  | "UNKNOWN";

export class ProviderError extends Error {
  public readonly provider: string;
  public readonly code: ProviderErrorCode;
  public readonly retryable: boolean;
  public readonly status?: number;
  public readonly cause?: unknown;

  constructor(params: {
    provider: string;
    message: string;
    code: ProviderErrorCode;
    retryable: boolean;
    status?: number;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "ProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.status = params.status;
    this.cause = params.cause;
  }
}

export class AllProvidersFailedError extends Error {
  public readonly errors: ProviderError[];

  constructor(errors: ProviderError[]) {
    super(
      `All providers failed: ${errors
        .map((e) => `${e.provider}[${e.code}]`)
        .join(", ")}`
    );
    this.name = "AllProvidersFailedError";
    this.errors = errors;
  }
}

export interface AIProvider {
  name: string;
  model: string;
  generate(request: AIRequest, context?: ProviderCallContext): Promise<AIResponse>;
}

export type FallbackPolicy = {
  perProviderTimeoutMs: number;
  maxRetriesPerProvider: number;
  retryDelayMs: number;
  shouldRetry?: (error: ProviderError, attempt: number) => boolean;
};

export type OrchestratorOptions = {
  providers: AIProvider[];
  policy: FallbackPolicy;
  logger?: Logger;
};

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);

    if (signal) {
      const onAbort = () => {
        clearTimeout(timer);
        reject(
          new ProviderError({
            provider: "orchestrator",
            message: "Operation aborted during sleep",
            code: "ABORTED",
            retryable: false,
          })
        );
      };

      if (signal.aborted) {
        onAbort();
        return;
      }

      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

function createTimeoutSignal(
  timeoutMs: number,
  parentSignal?: AbortSignal
): { signal: AbortSignal; cleanup: () => void } {
  const controller = new AbortController();

  const timeout = setTimeout(() => {
    controller.abort(new Error(`Timed out after ${timeoutMs}ms`));
  }, timeoutMs);

  const onParentAbort = () => {
    controller.abort(parentSignal?.reason ?? new Error("Parent aborted"));
  };

  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort(parentSignal.reason ?? new Error("Parent aborted"));
    } else {
      parentSignal.addEventListener("abort", onParentAbort, { once: true });
    }
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timeout);
      if (parentSignal) {
        parentSignal.removeEventListener("abort", onParentAbort);
      }
    },
  };
}

function normalizeUnknownError(provider: string, error: unknown): ProviderError {
  if (error instanceof ProviderError) {
    return error;
  }

  if (error instanceof Error) {
    if (error.name === "AbortError") {
      return new ProviderError({
        provider,
        message: error.message || "Request aborted",
        code: "ABORTED",
        retryable: false,
        cause: error,
      });
    }

    if (/timeout|timed out/i.test(error.message)) {
      return new ProviderError({
        provider,
        message: error.message,
        code: "TIMEOUT",
        retryable: true,
        cause: error,
      });
    }

    return new ProviderError({
      provider,
      message: error.message,
      code: "UNKNOWN",
      retryable: true,
      cause: error,
    });
  }

  return new ProviderError({
    provider,
    message: "Unknown provider error",
    code: "UNKNOWN",
    retryable: true,
    cause: error,
  });
}

async function callWithRetry(
  provider: AIProvider,
  request: AIRequest,
  context: ProviderCallContext,
  policy: FallbackPolicy
): Promise<AIResponse> {
  let lastError: ProviderError | undefined;

  for (let attempt = 1; attempt <= policy.maxRetriesPerProvider + 1; attempt++) {
    const { signal, cleanup } = createTimeoutSignal(
      policy.perProviderTimeoutMs,
      context.signal
    );

    const startedAt = Date.now();

    try {
      context.logger?.info("Calling provider", {
        provider: provider.name,
        model: provider.model,
        attempt,
        requestId: context.requestId,
      });

      const response = await provider.generate(request, {
        ...context,
        signal,
      });

      cleanup();

      context.logger?.info("Provider succeeded", {
        provider: provider.name,
        model: provider.model,
        attempt,
        latencyMs: Date.now() - startedAt,
        requestId: context.requestId,
      });

      return response;
    } catch (error) {
      cleanup();

      const normalized = normalizeUnknownError(provider.name, error);
      lastError = normalized;

      context.logger?.warn("Provider failed", {
        provider: provider.name,
        model: provider.model,
        attempt,
        code: normalized.code,
        retryable: normalized.retryable,
        message: normalized.message,
        requestId: context.requestId,
      });

      const shouldRetry =
        attempt <= policy.maxRetriesPerProvider &&
        normalized.retryable &&
        (policy.shouldRetry?.(normalized, attempt) ?? true);

      if (!shouldRetry) {
        throw normalized;
      }

      await sleep(policy.retryDelayMs, context.signal);
    }
  }

  throw (
    lastError ??
    new ProviderError({
      provider: provider.name,
      message: "Provider failed without specific error",
      code: "UNKNOWN",
      retryable: false,
    })
  );
}

export async function generateWithFallback(
  request: AIRequest,
  options: OrchestratorOptions,
  context: ProviderCallContext = {}
): Promise<AIResponse> {
  const logger = context.logger ?? options.logger ?? new ConsoleLogger();
  const errors: ProviderError[] = [];

  for (const provider of options.providers) {
    try {
      const response = await callWithRetry(
        provider,
        request,
        { ...context, logger },
        options.policy
      );

      return response;
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      errors.push(normalized);

      logger.warn("Falling back to next provider", {
        failedProvider: provider.name,
        code: normalized.code,
        message: normalized.message,
        requestId: context.requestId,
      });

      if (context.signal?.aborted) {
        throw new ProviderError({
          provider: provider.name,
          message: "Request aborted by caller",
          code: "ABORTED",
          retryable: false,
          cause: context.signal.reason,
        });
      }
    }
  }

  logger.error("All providers failed", {
    requestId: context.requestId,
    errors: errors.map((e) => ({
      provider: e.provider,
      code: e.code,
      message: e.message,
      retryable: e.retryable,
      status: e.status,
    })),
  });

  throw new AllProvidersFailedError(errors);
}
```

