## TypeScript 코드

```ts
type Provider = "openai" | "claude";

interface CandidateResponse {
  provider: Provider;
  content: string;
  latencyMs?: number;
  inputTokens?: number;
  outputTokens?: number;
  model?: string;
}

interface JudgeInput {
  userPrompt: string;
  systemPrompt?: string;
  expectedFormat?: "text" | "json" | "markdown" | "code";
  candidates: [CandidateResponse, CandidateResponse];
}

interface JudgeResult {
  winner: Provider | "tie";
  scores: Record<Provider, number>;
  reasons: string[];
  confidence: number;
  method: "rule" | "heuristic" | "llm";
  diagnostics?: {
    hardFailures: Record<Provider, string[]>;
    softSignals: Record<Provider, string[]>;
  };
}

interface JudgeOptions {
  enableLlmJudge?: boolean;
  llmJudgeThreshold?: number; // 점수 차가 이 값 미만이면 LLM judge 사용
  preferLowerLatency?: boolean;
  preferLowerCost?: boolean;
  maxReasonCount?: number;
}

const DEFAULT_OPTIONS: Required<JudgeOptions> = {
  enableLlmJudge: false,
  llmJudgeThreshold: 8,
  preferLowerLatency: true,
  preferLowerCost: true,
  maxReasonCount: 8,
};

export async function judgeBestResponse(
  input: JudgeInput,
  options: JudgeOptions = {}
): Promise<JudgeResult> {
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const [a, b] = input.candidates;

  const aEval = evaluateCandidate(input, a, opts);
  const bEval = evaluateCandidate(input, b, opts);

  // 1) Hard failure 우선 판정
  const aHardFail = aEval.hardFailures.length > 0;
  const bHardFail = bEval.hardFailures.length > 0;

  if (aHardFail && !bHardFail) {
    return buildResult(
      b.provider,
      a,
      b,
      aEval,
      bEval,
      "rule",
      0.95,
      [`${a.provider} failed hard checks: ${aEval.hardFailures.join("; ")}`],
      opts
    );
  }

  if (bHardFail && !aHardFail) {
    return buildResult(
      a.provider,
      a,
      b,
      aEval,
      bEval,
      "rule",
      0.95,
      [`${b.provider} failed hard checks: ${bEval.hardFailures.join("; ")}`],
      opts
    );
  }

  // 2) Heuristic score 비교
  const scoreDiff = Math.abs(aEval.score - bEval.score);
  const heuristicWinner =
    aEval.score > bEval.score
      ? a.provider
      : bEval.score > aEval.score
      ? b.provider
      : "tie";

  // 3) 점수 차가 충분하면 heuristic으로 종료
  if (heuristicWinner !== "tie" && scoreDiff >= opts.llmJudgeThreshold) {
    return buildResult(
      heuristicWinner,
      a,
      b,
      aEval,
      bEval,
      "heuristic",
      confidenceFromDiff(scoreDiff),
      collectReasons(a, b, aEval, bEval, heuristicWinner, opts),
      opts
    );
  }

