  winner: Provider | "tie";
  scores: Record<Provider, number>;
  reasons: string[];
  confidence: number; // 0~1
  method: "rule" | "heuristic" | "llm";
  diagnostics?: {
    hardFailures: Record<Provider, string[]>;
    softSignals: Record<Provider, string[]>;
  };
}
```

---

