}

/**
 * output 존재 여부/기본 품질 점수
 * 실제 production에서는 evaluator(LLM judge, regex, schema validation 등)로 확장 가능
 */
export function createOutputValidityRule<T = unknown>(
  weight: number,
  validator?: (output: T | undefined, candidate: ProviderResult<T>) => boolean
): ScoreRule<T> {
  return {
    name: "output_validity",
    weight,
    evaluate: ({ candidate }) => {
      if (!candidate.success) return 0;

      const isValid = validator
        ? validator(candidate.output, candidate)
        : candidate.output !== undefined && candidate.output !== null;

      return isValid ? 1 : 0;
    },
  };
}

/**
 * 문자열 응답 길이 기반 간단 점수 예시
 * 너무 짧은 답변을 낮게 평가
 */
export function createTextLengthRule(
  weight: number,
  options?: {
    minLength?: number;
    idealLength?: number;
    maxLength?: number;
  }
): ScoreRule<string> {
  const minLength = options?.minLength ?? 20;
  const idealLength = options?.idealLength ?? 200;
  const maxLength = options?.maxLength ?? 2000;

  return {
    name: "text_length",
    weight,
    evaluate: ({ candidate }) => {
      if (!candidate.success || typeof candidate.output !== "string") return 0;

      const len = candidate.output.trim().length;
      if (len < minLength) return 0;
      if (len === idealLength) return 1;
      if (len > maxLength) return 0.2;

      if (len < idealLength) {
        return clamp((len - minLength) / Math.max(1, idealLength - minLength));
      }

      // idealLength 초과 시 완만히 감소
      const decay = 1 - (len - idealLength) / Math.max(1, maxLength - idealLength);
      return clamp(Math.max(0.2, decay));
    },
  };
}

/**
 * JSON schema-like validation 예시
 * 실제로는 zod/ajv 사용 권장
 */
export function createRequiredFieldsRule<T extends Record<string, unknown>>(
  weight: number,
  requiredFields: (keyof T)[]
): ScoreRule<T> {
  return {
    name: "required_fields",
    weight,
    evaluate: ({ candidate }) => {
      if (!candidate.success || !candidate.output || typeof candidate.output !== "object") {
        return 0;
      }

      const output = candidate.output;
      const presentCount = requiredFields.filter((field) => {
        const value = output[field];
        return value !== undefined && value !== null;
      }).length;

      return clamp(presentCount / requiredFields.length);
    },
  };
}

export interface RankOptions<T = unknown> {
  rules: ScoreRule<T>[];
  /**
   * tie-breaker:
   * 음수면 a 우선, 양수면 b 우선, 0이면 동일
   */
  tieBreaker?: (a: RankedResult<T>, b: RankedResult<T>) => number;
}

export function rankProviders<T = unknown>(
  candidates: ProviderResult<T>[],
  options: RankOptions<T>
): RankedResult<T>[] {
  const { rules, tieBreaker } = options;

  const ranked: RankedResult<T>[] = candidates.map((candidate) => {
    const breakdown: ScoreBreakdown[] = rules.map((rule) => {
      const rawScore = clamp(rule.evaluate({ candidate, allCandidates: candidates }));
      const weightedScore = rawScore * rule.weight;

      return {
        rule: rule.name,
        weight: rule.weight,
        rawScore,
        weightedScore,
      };
    });

    const totalScore = breakdown.reduce((sum, item) => sum + item.weightedScore, 0);

    return {
      providerResult: candidate,
      totalScore,
      breakdown,
    };
  });

  ranked.sort((a, b) => {
    if (b.totalScore !== a.totalScore) {
      return b.totalScore - a.totalScore;
    }

    if (tieBreaker) {
      return tieBreaker(a, b);
    }

    // 기본 tie-breaker:
    // 1) success 우선
    // 2) latency 낮은 것 우선
    // 3) cost 낮은 것 우선
    if (a.providerResult.success !== b.providerResult.success) {
      return a.providerResult.success ? -1 : 1;
    }

    if (a.providerResult.latencyMs !== b.providerResult.latencyMs) {
      return a.providerResult.latencyMs - b.providerResult.latencyMs;
    }

    const aCost = a.providerResult.usage?.costUsd ?? Number.POSITIVE_INFINITY;
    const bCost = b.providerResult.usage?.costUsd ?? Number.POSITIVE_INFINITY;
    return aCost - bCost;
  });

  return ranked;
}

export function pickWinner<T = unknown>(
  candidates: ProviderResult<T>[],
  options: RankOptions<T>
): WinnerResult<T> {
  if (!candidates.length) {
    return {
      winner: null,
      ranking: [],
    };
  }

  const ranking = rankProviders(candidates, options);

  return {
    winner: ranking[0] ?? null,
    ranking,
  };
}
