export class SimplePlanner implements Planner {
  constructor(private readonly logger: Logger) {}

  async createPlan(input: TaskInput): Promise<Plan> {
    this.logger.info("Creating plan", {
      requestId: input.requestId,
      userGoal: input.userGoal
    });

    const steps: PlanStep[] = [
      {
        id: generateId("step"),
        type: "fetch_data",
        description: "Fetch source data relevant to the user goal",
        payload: {
          query: input.userGoal
        }
      },
      {
        id: generateId("step"),
        type: "transform_data",
        description: "Transform fetched data into structured insights"
      },
      {
        id: generateId("step"),
        type: "summarize",
        description: "Summarize the transformed insights for the user"
      }
    ];

    return {
      planId: generateId("plan"),
      steps,
      metadata: {
