```ts
import {
  Provider,
  SendMessageInput,
  SendMessageResult,
} from '../providers/Provider';

export class ProviderNotFoundError extends Error {
  constructor(channel: string) {
    super(`No provider found for channel: ${channel}`);
    this.name = 'ProviderNotFoundError';
  }
}

export class AllProvidersFailedError extends Error {
  constructor(public readonly errors: Array<{ provider: string; error: unknown }>) {
    super('All candidate providers failed');
    this.name = 'AllProvidersFailedError';
  }
}

export class ProviderRouter {
  constructor(private readonly providers: Provider[]) {
    if (providers.length === 0) {
      throw new Error('ProviderRouter requires at least one provider');
    }
  }

  getCandidates(input: SendMessageInput): Provider[] {
    const candidates = this.providers
      .filter((provider) => provider.canHandle(input))
      .sort((a, b) => a.priority - b.priority);

    if (candidates.length === 0) {
      throw new ProviderNotFoundError(input.channel);
    }

    return candidates;
  }

  async send(input: SendMessageInput): Promise<SendMessageResult> {
    const candidates = this.getCandidates(input);
    const errors: Array<{ provider: string; error: unknown }> = [];

    for (const provider of candidates) {
      try {
        return await provider.send(input);
      } catch (error) {
        errors.push({
          provider: provider.name,
          error,
        });
      }
    }

    throw new AllProvidersFailedError(errors);
  }
}
```

이 router는:

- 요청을 처리 가능한 provider만 고르고
- `priority` 순으로 정렬한 뒤
- 하나씩 시도하다가
- 실패하면 다음 provider로 fallback 합니다

