# 전체 예시 코드

```ts
// ai-orchestrator.ts

export type AIMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type AIRequest = {
  messages: AIMessage[];
  model?: string;
  temperature?: number;
  maxTokens?: number;
  timeoutMs?: number;
  metadata?: Record<string, unknown>;
};

export type AIUsage = {
  promptTokens?: number;
  completionTokens?: number;
  totalTokens?: number;
};

export type AIResponse = {
  provider: string;
  model: string;
  content: string;
  usage?: AIUsage;
  raw?: unknown;
};

export type ProviderErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "NETWORK"
  | "SERVER"
  | "UNKNOWN";

export class ProviderError extends Error {
  public readonly provider: string;
  public readonly code: ProviderErrorCode;
  public readonly retryable: boolean;
  public readonly cause?: unknown;
  public readonly status?: number;

  constructor(params: {
    provider: string;
    code: ProviderErrorCode;
    message: string;
    retryable: boolean;
    cause?: unknown;
    status?: number;
  }) {
    super(params.message);
    this.name = "ProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.cause = params.cause;
    this.status = params.status;
  }
}

export class OrchestrationError extends Error {
  public readonly errors: ProviderError[];

  constructor(message: string, errors: ProviderError[]) {
    super(message);
    this.name = "OrchestrationError";
    this.errors = errors;
  }
}

export interface AIProvider {
  name: string;
  generate(request: AIRequest): Promise<AIResponse>;
}

export type RetryOptions = {
  maxAttempts: number;
  baseDelayMs: number;
  maxDelayMs: number;
  shouldRetry?: (error: unknown) => boolean;
};

export type OrchestratorLogger = {
  info?: (message: string, meta?: Record<string, unknown>) => void;
  warn?: (message: string, meta?: Record<string, unknown>) => void;
  error?: (message: string, meta?: Record<string, unknown>) => void;
};

export type OrchestratorOptions = {
  retry?: RetryOptions;
  logger?: OrchestratorLogger;
  stopOnNonRetryableError?: boolean;
};

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function withTimeout<T>(
  promiseFactory: () => Promise<T>,
  timeoutMs: number,
  provider: string
): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      reject(
        new ProviderError({
          provider,
          code: "TIMEOUT",
          message: `Request timed out after ${timeoutMs}ms`,
          retryable: true,
        })
      );
    }, timeoutMs);
  });

  try {
    return await Promise.race([promiseFactory(), timeoutPromise]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

export async function retry<T>(
  fn: (attempt: number) => Promise<T>,
  options: RetryOptions
): Promise<T> {
  const {
    maxAttempts,
    baseDelayMs,
    maxDelayMs,
    shouldRetry = (error) =>
      error instanceof ProviderError ? error.retryable : false,
  } = options;

  let lastError: unknown;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;

      const canRetry = attempt < maxAttempts && shouldRetry(error);
      if (!canRetry) {
        throw error;
      }

      const backoff = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
      const jitter = Math.floor(Math.random() * 100);
      await sleep(backoff + jitter);
    }
  }

  throw lastError;
}

function normalizeUnknownError(provider: string, error: unknown): ProviderError {
  if (error instanceof ProviderError) {
    return error;
  }

  if (error instanceof Error) {
    return new ProviderError({
      provider,
      code: "UNKNOWN",
      message: error.message,
      retryable: false,
      cause: error,
    });
  }

  return new ProviderError({
    provider,
    code: "UNKNOWN",
    message: "Unknown provider error",
    retryable: false,
    cause: error,
  });
}

export async function generateWithFallback(
  providers: AIProvider[],
  request: AIRequest,
  options: OrchestratorOptions = {}
): Promise<AIResponse> {
  if (providers.length === 0) {
    throw new Error("At least one provider is required");
  }

  const logger = options.logger;
  const retryOptions: RetryOptions = options.retry ?? {
    maxAttempts: 2,
    baseDelayMs: 300,
    maxDelayMs: 2000,
  };

  const errors: ProviderError[] = [];

  for (const provider of providers) {
    logger?.info?.("Trying provider", {
      provider: provider.name,
      model: request.model,
    });

    try {
      const result = await retry(
        async (attempt) => {
          logger?.info?.("Provider attempt", {
            provider: provider.name,
            attempt,
          });

          return provider.generate(request);
        },
        retryOptions
      );

      logger?.info?.("Provider succeeded", {
        provider: provider.name,
        model: result.model,
      });

      return result;
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      errors.push(normalized);

      logger?.warn?.("Provider failed", {
        provider: provider.name,
        code: normalized.code,
        retryable: normalized.retryable,
        message: normalized.message,
        status: normalized.status,
      });

      if (options.stopOnNonRetryableError && !normalized.retryable) {
        throw new OrchestrationError(
          `Stopped on non-retryable error from provider: ${provider.name}`,
          errors
        );
      }
    }
  }

  logger?.error?.("All providers failed", {
    errors: errors.map((e) => ({
      provider: e.provider,
      code: e.code,
      message: e.message,
      retryable: e.retryable,
      status: e.status,
    })),
  });

  throw new OrchestrationError("All providers failed", errors);
}

