      if (!content) {
        throw new ProviderError({
          provider: this.name,
          code: "SERVER",
          message: "Invalid response format from Anthropic",
          retryable: true,
          cause: data,
          status: response.status,
        });
      }

      return {
        provider: this.name,
        model: data.model ?? request.model ?? this.model,
        content,
        usage: {
          promptTokens: data.usage?.input_tokens,
