      return new ProviderError({
        provider: this.name,
        code: "AUTH",
        message,
        retryable: false,
        cause: body,
        status,
      });
    }

    if (status === 429) {
      return new ProviderError({
        provider: this.name,
        code: "RATE_LIMIT",
        message,
        retryable: true,
        cause: body,
        status,
