# 전체 코드 예시

## 1) 타입 정의

```ts
// judge/types.ts
export type CandidateModel = 'openai' | 'claude';
export type JudgeWinner = CandidateModel | 'tie';

export interface JudgeInput {
  userPrompt: string;
  openaiResponse: string;
  claudeResponse: string;
  taskType?: 'general' | 'code' | 'json' | 'analysis' | 'creative';
  locale?: string; // e.g. 'ko', 'en'
  metadata?: Record<string, unknown>;
}

export interface RulePenalty {
  candidate: CandidateModel;
  reason: string;
  penalty: number; // positive number to subtract
}

export interface CandidateScoreBreakdown {
  instructionFollowing: number; // 0-10
  correctness: number; // 0-10
  completeness: number; // 0-10
  clarity: number; // 0-10
  safety: number; // 0-10
  conciseness: number; // 0-10
  codeQuality?: number; // 0-10
  total: number; // weighted total before penalties
}

export interface LlmJudgeResult {
  winner: JudgeWinner;
  confidence: number; // 0-1
  reasoning: string;
  scores: {
    openai: CandidateScoreBreakdown;
    claude: CandidateScoreBreakdown;
  };
}

export interface FinalJudgeResult {
  winner: JudgeWinner;
  confidence: number;
  reasoning: string;
  llmJudge: LlmJudgeResult | null;
  penalties: RulePenalty[];
  finalScores: {
    openai: number;
    claude: number;
  };
  trace?: {
    promptVersion: string;
    rawJudgeResponse?: string;
    durationMs?: number;
    usedFallback?: boolean;
  };
