# Rule-based precheck 구현

이 단계는 매우 중요합니다.  
LLM judge 이전에 **명백한 실패**를 잡아냅니다.

```ts
// judge/rules.ts
import { CandidateModel, JudgeInput, RulePenalty } from './types';

function isBlank(text: string): boolean {
  return !text || text.trim().length === 0;
}

function isTooShort(text: string, minChars = 20): boolean {
  return text.trim().length < minChars;
}

function looksLikeJsonRequest(prompt: string): boolean {
  const p = prompt.toLowerCase();
  return p.includes('json') || p.includes('json으로') || p.includes('json format');
}

function isValidJson(text: string): boolean {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
}

function looksLikeCodeRequest(prompt: string): boolean {
  const p = prompt.toLowerCase();
  return (
    p.includes('typescript') ||
    p.includes('javascript') ||
    p.includes('python') ||
    p.includes('code') ||
    p.includes('함수') ||
    p.includes('구현')
  );
}

function containsCodeBlock(text: string): boolean {
  return text.includes('```');
}

function detectLanguage(text: string): 'ko' | 'en' | 'unknown' {
  const hasKorean = /[가-힣]/.test(text);
  const hasEnglish = /[a-zA-Z]/.test(text);
  if (hasKorean && !hasEnglish) return 'ko';
  if (!hasKorean && hasEnglish) return 'en';
  if (hasKorean && hasEnglish) return 'ko'; // mixed but likely Korean context
  return 'unknown';
}

function languageMismatch(expected: string | undefined, text: string): boolean {
  if (!expected) return false;
  const detected = detectLanguage(text);
  if (expected === 'ko') return detected === 'en';
  if (expected === 'en') return detected === 'ko';
  return false;
}

function evaluateCandidate(
  candidate: CandidateModel,
  response: string,
  input: JudgeInput
): RulePenalty[] {
  const penalties: RulePenalty[] = [];

  if (isBlank(response)) {
    penalties.push({ candidate, reason: 'blank_response', penalty: 100 });
    return penalties;
  }

  if (isTooShort(response)) {
    penalties.push({ candidate, reason: 'too_short', penalty: 15 });
  }

  if (languageMismatch(input.locale, response)) {
    penalties.push({ candidate, reason: 'language_mismatch', penalty: 20 });
  }

  if (looksLikeJsonRequest(input.userPrompt) && !isValidJson(response)) {
    penalties.push({ candidate, reason: 'invalid_json_for_json_request', penalty: 25 });
  }

  if (looksLikeCodeRequest(input.userPrompt) && !containsCodeBlock(response)) {
    penalties.push({ candidate, reason: 'missing_code_block_for_code_request', penalty: 10 });
  }

  return penalties;
}

export function runRuleChecks(input: JudgeInput): RulePenalty[] {
  return [
    ...evaluateCandidate('openai', input.openaiResponse, input),
    ...evaluateCandidate('claude', input.claudeResponse, input),
  ];
}
```

