아래는 **scoreboard 기반으로 여러 provider 응답을 평가하고 최종 winner를 반환하는 TypeScript 코드**입니다.  
실무에서 바로 확장할 수 있도록 **정규화 → 점수 계산 → 정렬 → tie-breaker → winner 선택** 흐름으로 구성했습니다.

---

## 핵심 포인트

- provider 응답을 공통 포맷으로 정규화
- 평가 항목별 점수 계산
  - `latency`
  - `completeness`
  - `relevance`
  - `safety`
  - `cost`
- 가중치 기반 총점 계산
- 실패 응답 / 빈 응답 처리
- 동점 시 tie-breaker 적용
- 최종 `winner`와 전체 `scoreboard` 반환

---

## TypeScript 코드

```ts
/* eslint-disable no-console */

type ProviderName = "openai" | "anthropic" | "google" | "custom";

interface UserRequest {
  prompt: string;
  maxTokens?: number;
  temperature?: number;
}

interface ProviderRawResponse {
  provider: ProviderName;
  content?: string;
  latencyMs: number;
  costUsd: number;
  success: boolean;
  error?: string;
  metadata?: Record<string, unknown>;
}

interface NormalizedResponse {
  provider: ProviderName;
  content: string;
  latencyMs: number;
  costUsd: number;
  success: boolean;
  error?: string;
  metadata: Record<string, unknown>;
}

interface ScoreBreakdown {
  latency: number;       // 0..1
  completeness: number;  // 0..1
  relevance: number;     // 0..1
  safety: number;        // 0..1
  cost: number;          // 0..1
}

interface ScoreWeights {
  latency: number;
  completeness: number;
  relevance: number;
  safety: number;
  cost: number;
}

interface ScoredResponse {
  response: NormalizedResponse;
  breakdown: ScoreBreakdown;
  totalScore: number;
  rank?: number;
}

interface WinnerResult {
  winner: ScoredResponse | null;
  scoreboard: ScoredResponse[];
  reason: string;
}

interface EvaluationContext {
  request: UserRequest;
  expectedKeywords?: string[];
  maxAcceptableLatencyMs?: number;
  maxAcceptableCostUsd?: number;
  bannedWords?: string[];
}

const DEFAULT_WEIGHTS: ScoreWeights = {
  latency: 0.15,
  completeness: 0.20,
  relevance: 0.35,
  safety: 0.20,
  cost: 0.10,
};

function clamp(value: number, min = 0, max = 1): number {
  return Math.max(min, Math.min(max, value));
}

function normalizeResponse(raw: ProviderRawResponse): NormalizedResponse {
  return {
    provider: raw.provider,
    content: raw.content?.trim() ?? "",
    latencyMs: raw.latencyMs,
    costUsd: raw.costUsd,
    success: raw.success,
    error: raw.error,
    metadata: raw.metadata ?? {},
  };
}

/**
 * latency가 낮을수록 높은 점수
 */
function scoreLatency(latencyMs: number, maxAcceptableLatencyMs = 5000): number {
  if (latencyMs <= 0) return 0;
  if (latencyMs >= maxAcceptableLatencyMs) return 0;
  return clamp(1 - latencyMs / maxAcceptableLatencyMs);
}

/**
 * 응답 길이 기반 completeness 예시
 * 실제 운영에서는 schema 충족 여부, 필수 섹션 포함 여부 등을 함께 보는 것이 좋음
 */
function scoreCompleteness(content: string): number {
  const length = content.trim().length;
  if (length === 0) return 0;
  if (length < 50) return 0.3;
  if (length < 150) return 0.6;
  if (length < 400) return 0.85;
  return 1.0;
}

/**
 * expectedKeywords 포함 비율로 relevance 계산
 * 실제 운영에서는 embedding similarity / reranker / LLM judge로 대체 가능
 */
function scoreRelevance(content: string, expectedKeywords: string[] = []): number {
  if (!content.trim()) return 0;
  if (expectedKeywords.length === 0) return 0.7;

  const lower = content.toLowerCase();
  const matched = expectedKeywords.filter((kw) =>
    lower.includes(kw.toLowerCase())
  ).length;

  return clamp(matched / expectedKeywords.length);
}

/**
 * bannedWords 포함 여부로 safety 계산
 * 실제 운영에서는 moderation API / policy engine 연동 권장
 */
function scoreSafety(content: string, bannedWords: string[] = []): number {
  if (!content.trim()) return 0;

  const lower = content.toLowerCase();
  const violations = bannedWords.filter((w) =>
    lower.includes(w.toLowerCase())
  ).length;

  if (violations === 0) return 1.0;
  if (violations === 1) return 0.5;
  return 0.0;
}

/**
 * 비용이 낮을수록 높은 점수
 */
function scoreCost(costUsd: number, maxAcceptableCostUsd = 0.05): number {
  if (costUsd < 0) return 0;
  if (costUsd >= maxAcceptableCostUsd) return 0;
  return clamp(1 - costUsd / maxAcceptableCostUsd);
}

function evaluateResponse(
  response: NormalizedResponse,
  context: EvaluationContext,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): ScoredResponse {
  if (!response.success || !response.content) {
    return {
      response,
      breakdown: {
        latency: 0,
        completeness: 0,
        relevance: 0,
        safety: 0,
        cost: 0,
      },
      totalScore: 0,
    };
  }

  const breakdown: ScoreBreakdown = {
    latency: scoreLatency(
      response.latencyMs,
      context.maxAcceptableLatencyMs ?? 5000
    ),
    completeness: scoreCompleteness(response.content),
    relevance: scoreRelevance(
      response.content,
      context.expectedKeywords ?? []
    ),
    safety: scoreSafety(
      response.content,
      context.bannedWords ?? []
    ),
    cost: scoreCost(
      response.costUsd,
      context.maxAcceptableCostUsd ?? 0.05
    ),
  };

  const totalScore =
    breakdown.latency * weights.latency +
    breakdown.completeness * weights.completeness +
    breakdown.relevance * weights.relevance +
    breakdown.safety * weights.safety +
    breakdown.cost * weights.cost;

  return {
    response,
    breakdown,
    totalScore: Number(totalScore.toFixed(6)),
  };
}

/**
 * tie-breaker 포함 정렬 규칙
 * 1) totalScore desc
 * 2) safety desc
 * 3) relevance desc
 * 4) latency asc
 * 5) cost asc
 */
function compareScoredResponses(a: ScoredResponse, b: ScoredResponse): number {
  if (b.totalScore !== a.totalScore) {
    return b.totalScore - a.totalScore;
  }

  if (b.breakdown.safety !== a.breakdown.safety) {
    return b.breakdown.safety - a.breakdown.safety;
  }

  if (b.breakdown.relevance !== a.breakdown.relevance) {
    return b.breakdown.relevance - a.breakdown.relevance;
  }

  if (a.response.latencyMs !== b.response.latencyMs) {
    return a.response.latencyMs - b.response.latencyMs;
  }

  if (a.response.costUsd !== b.response.costUsd) {
    return a.response.costUsd - b.response.costUsd;
  }

  return 0;
}

function buildScoreboard(
  rawResponses: ProviderRawResponse[],
  context: EvaluationContext,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): WinnerResult {
  const normalized = rawResponses.map(normalizeResponse);
  const scored = normalized.map((r) => evaluateResponse(r, context, weights));

  const valid = scored.filter(
    (s) => s.response.success && s.response.content.trim().length > 0
  );

  if (valid.length === 0) {
    return {
      winner: null,
      scoreboard: scored,
      reason: "No valid provider responses available.",
    };
  }

  const sorted = [...scored]
    .sort(compareScoredResponses)
    .map((item, index) => ({
      ...item,
      rank: index + 1,
    }));

  const winner =
    sorted.find(
      (s) => s.response.success && s.response.content.trim().length > 0
    ) ?? null;

  return {
    winner,
    scoreboard: sorted,
    reason: winner
      ? `Winner selected by weighted scoreboard: ${winner.response.provider}`
      : "No valid winner found.",
  };
}
```

