    ...item,
    rank: index + 1,
  }));

  const winner = sorted.find((s) => s.response.success && s.response.content.trim().length > 0) ?? null;

  return {
    winner,
    scoreboard: sorted,
    reason: winner
      ? `Winner selected by weighted scoreboard: ${winner.response.provider}`
      : "No valid winner found.",
  };
}
