  latency: 0.15,
  completeness: 0.20,
  relevance: 0.35,
  safety: 0.20,
  cost: 0.10,
};

function clamp(value: number, min = 0, max = 1): number {
  return Math.max(min, Math.min(max, value));
}

function normalizeResponse(raw: ProviderRawResponse): NormalizedResponse {
  return {
    provider: raw.provider,
    content: raw.content?.trim() ?? "",
    latencyMs: raw.latencyMs,
    costUsd: raw.costUsd,
    success: raw.success,
    error: raw.error,
    metadata: raw.metadata ?? {},
  };
}

/**
 * latency가 낮을수록 높은 점수
 */
function scoreLatency(latencyMs: number, maxAcceptableLatencyMs = 5000): number {
  if (latencyMs <= 0) return 0;
  if (latencyMs >= maxAcceptableLatencyMs) return 0;
  return clamp(1 - latencyMs / maxAcceptableLatencyMs);
}

/**
 * 응답 길이 기반 completeness 예시
 * 실제 운영에서는 schema 충족 여부, 필수 섹션 포함 여부 등을 함께 보는 것이 좋음
 */
