 * 실제 운영에서는 embedding similarity / reranker / LLM judge로 대체 가능
 */
function scoreRelevance(content: string, expectedKeywords: string[] = []): number {
  if (!content.trim()) return 0;
  if (expectedKeywords.length === 0) return 0.7;

  const lower = content.toLowerCase();
  const matched = expectedKeywords.filter((kw) =>
    lower.includes(kw.toLowerCase())
  ).length;

  return clamp(matched / expectedKeywords.length);
}

/**
 * bannedWords 포함 여부로 safety 계산
 * 실제 운영에서는 moderation API / policy engine 연동 권장
 */
function scoreSafety(content: string, bannedWords: string[] = []): number {
  if (!content.trim()) return 0;

  const lower = content.toLowerCase();
  const violations = bannedWords.filter((w) =>
    lower.includes(w.toLowerCase())
  ).length;

  if (violations === 0) return 1.0;
  if (violations === 1) return 0.5;
  return 0.0;
}

/**
 * 비용이 낮을수록 높은 점수
