```ts
import {
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types";
import { nowIso, sleep, toErrorMessage } from "./utils";

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

type ExecutionContext = {
  stepOutputs: Map<string, unknown>;
  lastOutput?: unknown;
};

export class SimpleExecutor implements Executor {
  async execute(plan: Plan): Promise<ExecutionResult> {
    const startedAt = nowIso();
    const stepResults: StepExecutionResult[] = [];
    const context: ExecutionContext = {
      stepOutputs: new Map()
    };

    for (const step of plan.steps) {
      const result = await this.executeStep(step, context);
      stepResults.push(result);

      if (result.status === "success") {
        context.stepOutputs.set(step.id, result.output);
        context.lastOutput = result.output;
      } else {
        // 하나라도 실패하면 이후 step은 중단
        break;
      }
    }

    return {
      planId: plan.planId,
      stepResults,
      startedAt,
      finishedAt: nowIso()
    };
  }

  private async executeStep(
    step: PlanStep,
    context: ExecutionContext
  ): Promise<StepExecutionResult> {
    const startedAt = nowIso();

    try {
      let output: unknown;

      switch (step.type) {
        case "fetch_data":
          output = await this.handleFetchData(step);
          break;
        case "transform_data":
          output = await this.handleTransformData(context.lastOutput);
          break;
        case "summarize":
          output = await this.handleSummarize(context.lastOutput);
          break;
        default: {
          const exhaustiveCheck: never = step.type;
          throw new Error(`Unsupported step type: ${exhaustiveCheck}`);
        }
      }

      return {
        stepId: step.id,
        status: "success",
        output,
        startedAt,
        finishedAt: nowIso()
      };
    } catch (error) {
      return {
        stepId: step.id,
        status: "failed",
        error: toErrorMessage(error),
        startedAt,
        finishedAt: nowIso()
      };
    }
  }

  private async handleFetchData(step: PlanStep): Promise<unknown> {
    await sleep(200);

    const query = step.payload?.query;
    if (typeof query !== "string" || query.trim() === "") {
      throw new Error("Invalid query for fetch_data step");
    }

    return {
      source: "mock-datasource",
      items: [
        { id: 1, text: `Data point A for "${query}"` },
        { id: 2, text: `Data point B for "${query}"` },
        { id: 3, text: `Data point C for "${query}"` }
      ]
    };
  }

  private async handleTransformData(input: unknown): Promise<unknown> {
    await sleep(150);

    if (
      !input ||
      typeof input !== "object" ||
      !("items" in input) ||
      !Array.isArray((input as { items: unknown[] }).items)
    ) {
      throw new Error("Transform step requires fetched items");
    }

    const items = (input as { items: Array<{ id: number; text: string }> }).items;

    return {
      totalItems: items.length,
      normalizedTexts: items.map((item) => item.text.toUpperCase()),
      keywords: ["DATA", "POINT"]
    };
  }

  private async handleSummarize(input: unknown): Promise<unknown> {
    await sleep(100);

    if (
      !input ||
      typeof input !== "object" ||
      !("normalizedTexts" in input) ||
      !Array.isArray((input as { normalizedTexts: string[] }).normalizedTexts)
    ) {
      throw new Error("Summarize step requires transformed data");
    }

    const transformed = input as {
      totalItems: number;
      normalizedTexts: string[];
      keywords: string[];
    };

    return {
      summary: `Processed ${transformed.totalItems} items. Keywords: ${transformed.keywords.join(", ")}`,
      preview: transformed.normalizedTexts.slice(0, 2)
    };
  }
}
