## 7) `src/judge.ts`

```ts
import { ExecutionResult, JudgeResult, Plan } from "./types";

export interface Judge {
  evaluate(plan: Plan, execution: ExecutionResult): Promise<JudgeResult>;
}

export class SimpleJudge implements Judge {
  async evaluate(plan: Plan, execution: ExecutionResult): Promise<JudgeResult> {
    const failedSteps = execution.stepResults.filter(
      (result) => result.status === "failed"
    );

    if (failedSteps.length > 0) {
      return {
        decision: "retry",
        reason: `Execution failed at step ${failedSteps[0].stepId}: ${failedSteps[0].error}`,
        score: 20
      };
    }

    if (execution.stepResults.length !== plan.steps.length) {
      return {
        decision: "rejected",
        reason: "Execution did not complete all planned steps",
        score: 40
      };
    }

    const lastResult = execution.stepResults[execution.stepResults.length - 1];
    const hasSummary =
      lastResult?.status === "success" &&
      typeof lastResult.output === "object" &&
      lastResult.output !== null &&
      "summary" in lastResult.output;

    if (!hasSummary) {
      return {
        decision: "rejected",
        reason: "Final output does not contain a valid summary",
        score: 50
      };
    }

    return {
      decision: "approved",
      reason: "All steps executed successfully and final summary is valid",
      score: 95
    };
  }
}
```

