# 5) 타입 정의: `src/types.ts`

오케스트레이션의 핵심 타입입니다.

```ts
export type WorkflowInput = {
  requestId: string;
  userGoal: string;
};

export type PlanStepType = "fetch_data" | "transform_data" | "summarize";

export type PlanStep = {
  id: string;
  type: PlanStepType;
  description: string;
  payload?: Record<string, unknown>;
};

export type Plan = {
  planId: string;
  steps: PlanStep[];
  createdAt: string;
};

export type StepExecutionStatus = "success" | "failed";

export type StepExecutionResult = {
  stepId: string;
  status: StepExecutionStatus;
  output?: unknown;
  error?: string;
  startedAt: string;
  finishedAt: string;
};

export type ExecutionResult = {
  planId: string;
  stepResults: StepExecutionResult[];
  startedAt: string;
  finishedAt: string;
};

export type JudgeDecision = "approved" | "rejected" | "retry";

export type JudgeResult = {
  decision: JudgeDecision;
  reason: string;
  score: number;
};

export type WorkflowResult = {
  input: WorkflowInput;
  plan: Plan;
  execution: ExecutionResult;
  judge: JudgeResult;
};
